from collections import deque

def get_components(grid):
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    components = {}  # color → list of (r,c)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] not in components:
                components[grid[r][c]] = []

    # Process each component
    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if (r,c) not in visited:
                component = []
                queue = [(r,c)]
                while queue:
                    cr, cc = queue.pop(0)
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    component.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
